function suppliedSource(reader,r,p,view){const value=reader(r,p);assert(view.nativeAuthentic(value,r,p),'Current-runtime preservation source drift: Unauthentic supplied source at '+r+':'+p);return value;}
function suppliedContent(reader,r,p,view){const value=reader(r,p);assert(view.nativeContentAuthentic(value,r,p),'Current-runtime preservation source drift: Unauthentic supplied content at '+r+':'+p);return value;}
function suppliedDiff(reader,a,b,view){const value=reader(a,b);assert.deepEqual(sorted(value),sorted(diff(a==='HEAD'?view.rawHead:a,b==='HEAD'?view.rawHead:b)),'Current-runtime preservation source drift: Supplied diff changed at '+a+'..'+b);return value;}
function suppliedAncestor(reader,a,b,view){const value=reader(a,b);ancestor(a==='HEAD'?view.rawHead:a,b==='HEAD'?view.rawHead:b);assert.notEqual(value,false,'Current-runtime preservation source drift: Supplied ancestry changed at '+a+'..'+b);return value;}
const current=(r,v)=>r==='HEAD'||r===v.rawHead||r===v.head;
export function currentRuntimePreservationAuthenticatedRead(reader,view,{defaultReader=false}={}){
 return(r,p)=>useView(view,()=>{if(current(r,view)&&view.head!==view.rawHead){suppliedSource(reader,'HEAD',p,view);suppliedSource(reader,view.rawHead,p,view);return suppliedSource(reader,view.head,p,view);}return suppliedSource(reader,r,p,view);});
}
export function currentRuntimePreservationAuthenticatedContent(reader,view){return(r,p)=>useView(view,()=>{if(current(r,view)&&view.head!==view.rawHead){suppliedContent(reader,'HEAD',p,view);suppliedContent(reader,view.rawHead,p,view);return suppliedContent(reader,view.head,p,view);}return suppliedContent(reader,r,p,view);});}
export function currentRuntimePreservationAuthenticatedDiff(reader,view){return(a,b)=>useView(view,()=>{if(current(b,view)&&view.head!==view.rawHead){for(const r of['HEAD',view.rawHead])suppliedDiff(reader,a,r,view);return suppliedDiff(reader,a,view.head,view);}return suppliedDiff(reader,a,b,view);});}
export function currentRuntimePreservationAuthenticatedAncestor(reader,view){return(a,b)=>useView(view,()=>{if(current(b,view)&&view.head!==view.rawHead){for(const r of['HEAD',view.rawHead])suppliedAncestor(reader,a,r,view);return suppliedAncestor(reader,a,view.head,view);}return suppliedAncestor(reader,a,b,view);});}
export function currentRuntimePreservationLegacyRead(reader,view){return(r,p)=>{if((r==='HEAD'||r===view.rawHead)&&view.affected(p)){const a=reader('HEAD',p),b=reader(view.rawHead,p);if(a!==b&&!(view.authentic(a,'HEAD',p)&&view.authentic(b,view.rawHead,p)))return r==='HEAD'?a:b;return reader(view.head,p);}return reader(r,p);};}
// Historical configuration comparison only; production files remain exact GP ON.
export function withoutCurrentRuntimePreservationFlag(config){
 const view=currentRuntimePreservationHistoricalView();if(view.head===view.rawHead)return config;
 assert.equal(config,content(view.rawHead,'wrangler.jsonc'),'Only the exact accepted current configuration may enter a historical comparison');return content(view.head,'wrangler.jsonc');
}
